"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/scroll-narrative.module.css";

export interface ScrollNarrativeChapter {
  id: string;
  step: string;
  title: string;
  summary: string;
  metric: string;
}

export interface ScrollNarrativeProps {
  /** Narrative chapters */
  chapters?: ScrollNarrativeChapter[];
  /** Active chapter index (0 to chapters.length - 1) */
  activeChapter?: number;
  /** Progress percentage (0 to 100) */
  progress?: number;
  /** Pin visual telemetry card */
  pinStage?: boolean;
  /** Optional className */
  className?: string;
}

const DEFAULT_CHAPTERS: ScrollNarrativeChapter[] = [
  {
    id: "discover",
    step: "01 // DISCOVER",
    title: "Inspect Live Motion Primitives",
    summary: "Test real spring physics, SVG morphs, and canvas constellations directly in the browser.",
    metric: "24 Verified Primitives",
  },
  {
    id: "customize",
    step: "02 // CUSTOMIZE",
    title: "Tune Physics & Tokens",
    summary: "Adjust stiffness, damping, blur, and speed while watching the JSX usage code update live.",
    metric: "Zero Lock-In Source",
  },
  {
    id: "ship",
    step: "03 // DEPLOY",
    title: "Install via CLI or Package",
    summary: "Run npx motionfoundry add or import named primitives from @motionfoundry/ui.",
    metric: "100% TypeScript Typed",
  },
];

export function ScrollNarrative({
  chapters = DEFAULT_CHAPTERS,
  activeChapter = 0,
  progress = 35,
  pinStage = true,
  className = "",
}: ScrollNarrativeProps) {
  const [currentIdx, setCurrentIdx] = React.useState(activeChapter);
  const prefersReducedMotion = useReducedMotion();

  React.useEffect(() => {
    setCurrentIdx(Math.min(Math.max(activeChapter, 0), chapters.length - 1));
  }, [activeChapter, chapters.length]);

  const current = chapters[currentIdx] ?? chapters[0];

  return (
    <div className={`${styles.container} ${className}`.trim()}>
      <div className={styles.progressHeader}>
        <span className={styles.progressLabel}>Narrative Progress</span>
        <div className={styles.progressBar}>
          <div
            className={styles.progressFill}
            style={{ width: `${Math.min(100, Math.max(0, progress))}%` }}
          />
        </div>
        <span className={styles.progressValue}>{progress}%</span>
      </div>

      <div className={styles.grid}>
        <div className={styles.chapterList} role="tablist" aria-label="Storytelling chapters">
          {chapters.map((ch, idx) => {
            const active = idx === currentIdx;
            return (
              <button
                key={ch.id}
                type="button"
                role="tab"
                aria-selected={active}
                onClick={() => setCurrentIdx(idx)}
                className={`${styles.chapterItem} ${active ? styles.chapterActive : ""}`.trim()}
              >
                <span className={styles.stepTag}>{ch.step}</span>
                <span className={styles.chapterTitle}>{ch.title}</span>
              </button>
            );
          })}
        </div>

        {pinStage && current && (
          <motion.div
            key={current.id}
            initial={prefersReducedMotion ? false : { opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.38, ease: [0.16, 1, 0.3, 1] }}
            className={styles.visualStage}
          >
            <span className={styles.metricPill}>{current.metric}</span>
            <h4 className={styles.stageHeadline}>{current.title}</h4>
            <p className={styles.stageSummary}>{current.summary}</p>
          </motion.div>
        )}
      </div>
    </div>
  );
}

.container {
  width: 100%;
  border-radius: 0.85rem;
  border: 1px solid var(--mf-surface-raised, #25252f);
  background-color: var(--mf-bg, #0d0d12);
  padding: 1.25rem;
  color: var(--mf-fg, #f4f4f6);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.progressHeader {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.progressLabel,
.progressValue {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.7rem;
  color: var(--mf-muted, #a1a1aa);
}

.progressBar {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background-color: #1f1f29;
  overflow: hidden;
}

.progressFill {
  height: 100%;
  background-color: var(--mf-fg, #f4f4f6);
  transition: width 220ms ease;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 1rem;
  align-items: stretch;
}

.chapterList {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.chapterItem {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.15rem;
  padding: 0.65rem 0.85rem;
  border-radius: 0.55rem;
  border: 1px solid var(--mf-surface-raised, #22222c);
  background-color: var(--mf-surface, #121218);
  color: var(--mf-muted, #a1a1aa);
  text-align: left;
  cursor: pointer;
}

.chapterActive {
  border-color: var(--mf-border-strong, #52525b);
  background-color: #1a1a24;
  color: var(--mf-fg, #f4f4f6);
}

.stepTag {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.65rem;
  color: var(--mf-subtle, #71717a);
}

.chapterTitle {
  font-size: 0.82rem;
  font-weight: 600;
}

.visualStage {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.45rem;
  padding: 1.15rem;
  border-radius: 0.65rem;
  border: 1px solid var(--mf-border, #2b2b36);
  background-color: #13131b;
}

.metricPill {
  align-self: flex-start;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.68rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--mf-border, #323240);
  color: var(--mf-fg, #e4e4e7);
}

.stageHeadline {
  margin: 0;
  font-size: 0.98rem;
  font-weight: 600;
}

.stageSummary {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--mf-muted, #a1a1aa);
}

@media (prefers-reduced-motion: reduce) {
  .progressFill {
    transition: none;
  }
}

